"use strict";

/**
 * Human‑readable millisecond conversion utility.
 *
 * The original source was wrapped in a custom CommonJS loader.  This
 * reconstruction removes the loader while preserving the exact
 * behaviour of the exported function.
 *
 * @param {string|number} val      A duration string (e.g. "2h") or a number of milliseconds.
 * @param {Object} [options]       Optional settings.
 * @param {boolean} [options.long] If true, return a long format (e.g. "2 hours").
 * @returns {number|string}        Milliseconds when parsing a string, otherwise a formatted string.
 * @throws {Error}                When `val` is neither a non‑empty string nor a finite number.
 */
const ms = (() => {
  // Base units in milliseconds
  const s = 1_000;          // seconds
  const m = s * 60;         // minutes
  const h = m * 60;         // hours
  const d = h * 24;         // days
  const w = d * 7;          // weeks
  const y = d * 365.25;     // years (average, accounting for leap years)

  /** Parse a duration string into milliseconds. */
  function parse(str) {
    str = String(str);
    if (str.length > 100) return; // guard against absurdly long inputs

    const match = /^(-?(?:\d+)?\.?\d+) *(milliseconds?|msecs?|ms|seconds?|secs?|s|minutes?|mins?|m|hours?|hrs?|h|days?|d|weeks?|w|years?|yrs?|y)?$/i.exec(str);
    if (!match) return;

    const n = parseFloat(match[1]);
    const unit = (match[2] || "ms").toLowerCase();

    switch (unit) {
      case "years":
      case "year":
      case "yrs":
      case "yr":
      case "y":
        return n * y;
      case "weeks":
      case "week":
      case "w":
        return n * w;
      case "days":
      case "day":
      case "d":
        return n * d;
      case "hours":
      case "hour":
      case "hrs":
      case "hr":
      case "h":
        return n * h;
      case "minutes":
      case "minute":
      case "mins":
      case "min":
      case "m":
        return n * m;
      case "seconds":
      case "second":
      case "secs":
      case "sec":
      case "s":
        return n * s;
      case "milliseconds":
      case "millisecond":
      case "msecs":
      case "msec":
      case "ms":
        return n;
      default:
        return undefined;
    }
  }

  /** Short human‑readable format (e.g. "2h", "5d"). */
  function fmtShort(ms) {
    const abs = Math.abs(ms);
    if (abs >= d) return Math.round(ms / d) + "d";
    if (abs >= h) return Math.round(ms / h) + "h";
    if (abs >= m) return Math.round(ms / m) + "m";
    if (abs >= s) return Math.round(ms / s) + "s";
    return ms + "ms";
  }

  /** Helper for pluralisation in the long format. */
  function plural(ms, abs, unitMs, name) {
    const isPlural = abs >= unitMs * 1.5;
    return Math.round(ms / unitMs) + " " + name + (isPlural ? "s" : "");
  }

  /** Long human‑readable format (e.g. "2 hours", "5 days"). */
  function fmtLong(ms) {
    const abs = Math.abs(ms);
    if (abs >= d) return plural(ms, abs, d, "day");
    if (abs >= h) return plural(ms, abs, h, "hour");
    if (abs >= m) return plural(ms, abs, m, "minute");
    if (abs >= s) return plural(ms, abs, s, "second");
    return ms + " ms";
  }

  /** Exported function – mirrors the original module's API. */
  return function (val, options) {
    options = options || {};
    const type = typeof val;

    if (type === "string" && val.length > 0) {
      return parse(val);
    }
    if (type === "number" && isFinite(val)) {
      return options.long ? fmtLong(val) : fmtShort(val);
    }
    throw new Error(
      "val is not a non-empty string or a valid number. val=" + JSON.stringify(val)
    );
  };
})();

module.exports = ms;

"use strict";

/**
 * Escape HTML characters.
 *
 * This implementation mirrors the logic found in the bundled
 * `escape-html` module. It scans the input string for the characters
 * `" ' & < >` and replaces them with their corresponding HTML entities.
 *
 * @param {*} input - Any value that will be coerced to a string.
 * @returns {string} The escaped string.
 */
function escapeHtml(input) {
  const str = String(input);
  const ESCAPE_REGEX = /["'&<>]/;
  const firstMatch = ESCAPE_REGEX.exec(str);
  if (!firstMatch) return str; // fast path – nothing to escape

  let result = "";
  let last = 0; // index after the last processed character

  // Start iterating at the first matched character; continue to the end.
  for (let i = firstMatch.index; i < str.length; i++) {
    let replacement;
    switch (str.charCodeAt(i)) {
      case 34: // "
        replacement = "&quot;";
        break;
      case 38: // &
        replacement = "&amp;";
        break;
      case 39: // '
        replacement = "&#39;";
        break;
      case 60: // <
        replacement = "&lt;";
        break;
      case 62: // >
        replacement = "&gt;";
        break;
      default:
        continue; // character does not need escaping
    }

    // Append the substring that did not need escaping.
    if (i !== last) {
      result += str.substring(last, i);
    }

    // Append the escaped entity and move the cursor.
    result += replacement;
    last = i + 1;
  }

  // Append any trailing characters after the last escaped one.
  return last !== str.length ? result + str.substring(last) : result;
}

/**
 * Deeply retrieve a value from an object using a dot‑separated path.
 *
 * The function walks the object hierarchy according to `path`. If at any
 * point the traversal hits `undefined` (or the supplied `emptyValue`), the
 * loop stops and the `fallback` value is returned.
 *
 * @param {Object} obj          - The object to query.
 * @param {string|string[]} path - Property path, either as a string
 *                                 (`"a.b.c"`) or an array of keys.
 * @param {*} [fallback]        - Value to return when the resolved value
 *                                 equals `emptyValue`.
 * @param {*} [emptyValue]      - Sentinel that signals a missing value.
 *                                 Defaults to `undefined`.
 * @returns {*} The resolved value or `fallback`.
 */
function dlv(obj, path, fallback, emptyValue) {
  const parts = typeof path === "string" ? path.split(".") : path;
  for (let i = 0; i < parts.length; i++) {
    obj = obj ? obj[parts[i]] : emptyValue;
  }
  return obj === emptyValue ? fallback : obj;
}

/* Export the utilities in a CommonJS‑compatible way. */
module.exports = {
  escapeHtml,
  dlv,
};

/*!
