"use strict";

/**
 * Minimal implementation of the `kleur` library.
 *
 * This file is a cleaned‑up version of the original source that lives in
 * `benchmarks/reconstruct/.cache/kleur/index.js`.  It provides a small set of
 * ANSI colour/formatting helpers that can be used both as plain functions
 * (`red('text')`) and as a chainable API (`kleur.red().bold('text')`).
 *
 * The implementation follows the original behaviour:
 *   • Colours are enabled unless the environment explicitly disables them.
 *   • The `chain` function creates a context that remembers which styles have
 *     been applied so that subsequent calls add the appropriate opening/closing
 *     sequences.
 *   • When colours are disabled the functions simply return the original string.
 */

let FORCE_COLOR;
let NODE_DISABLE_COLORS;
let NO_COLOR;
let TERM;
let isTTY = true;

// Detect environment variables when running under Node.
if (typeof process !== "undefined") {
  ({ FORCE_COLOR, NODE_DISABLE_COLORS, NO_COLOR, TERM } = process.env || {});
  isTTY = !!(process.stdout && process.stdout.isTTY);
}

/**
 * Core object that holds all style functions.
 *
 * The `enabled` flag mirrors the logic used by the original `kleur` package.
 */
const $ = {
  enabled:
    !NODE_DISABLE_COLORS &&
    NO_COLOR == null &&
    TERM !== "dumb" &&
    (FORCE_COLOR != null && FORCE_COLOR !== "0" || isTTY),

  // modifiers
  reset: init(0, 0),
  bold: init(1, 22),
  dim: init(2, 22),
  italic: init(3, 23),
  underline: init(4, 24),
  inverse: init(7, 27),
  hidden: init(8, 28),
  strikethrough: init(9, 29),

  // foreground colours
  black: init(30, 39),
  red: init(31, 39),
  green: init(32, 39),
  yellow: init(33, 39),
  blue: init(34, 39),
  magenta: init(35, 39),
  cyan: init(36, 39),
  white: init(37, 39),
  gray: init(90, 39),
  grey: init(90, 39),

  // background colours
  bgBlack: init(40, 49),
  bgRed: init(41, 49),
  bgGreen: init(42, 49),
  bgYellow: init(43, 49),
  bgBlue: init(44, 49),
  bgMagenta: init(45, 49),
  bgCyan: init(46, 49),
  bgWhite: init(47, 49)
};

/**
 * Apply a list of style blocks to a string.
 *
 * @param {Array<{open:string,close:string,rgx:RegExp}>} arr   List of style blocks.
 * @param {string} str                                         Input string.
 * @returns {string}                                           Styled string.
 */
function run(arr, str) {
  let beg = "";
  let end = "";

  for (let i = 0; i < arr.length; i++) {
    const blk = arr[i];
    beg += blk.open;
    end += blk.close;

    // If the closing sequence already appears inside the string we need to
    // re‑order it so that nesting works correctly.
    if (str.indexOf(blk.close) !== -1) {
      str = str.replace(blk.rgx, blk.close + blk.open);
    }
  }

  return beg + str + end;
}

/**
 * Create a chainable context that remembers which styles have been applied.
 *
 * @param {Array<number>} has   List of opening codes that have been used.
 * @param {Array<Object>} keys  Corresponding style block objects.
 * @returns {Object}            Context with bound style methods.
 */
function chain(has, keys) {
  const ctx = { has, keys };

  // Bind every style function to the new context.
  ctx.reset = $.reset.bind(ctx);
  ctx.bold = $.bold.bind(ctx);
  ctx.dim = $.dim.bind(ctx);
  ctx.italic = $.italic.bind(ctx);
  ctx.underline = $.underline.bind(ctx);
  ctx.inverse = $.inverse.bind(ctx);
  ctx.hidden = $.hidden.bind(ctx);
  ctx.strikethrough = $.strikethrough.bind(ctx);
  ctx.black = $.black.bind(ctx);
  ctx.red = $.red.bind(ctx);
  ctx.green = $.green.bind(ctx);
  ctx.yellow = $.yellow.bind(ctx);
  ctx.blue = $.blue.bind(ctx);
  ctx.magenta = $.magenta.bind(ctx);
  ctx.cyan = $.cyan.bind(ctx);
  ctx.white = $.white.bind(ctx);
  ctx.gray = $.gray.bind(ctx);
  ctx.grey = $.grey.bind(ctx);
  ctx.bgBlack = $.bgBlack.bind(ctx);
  ctx.bgRed = $.bgRed.bind(ctx);
  ctx.bgGreen = $.bgGreen.bind(ctx);
  ctx.bgYellow = $.bgYellow.bind(ctx);
  ctx.bgBlue = $.bgBlue.bind(ctx);
  ctx.bgMagenta = $.bgMagenta.bind(ctx);
  ctx.bgCyan = $.bgCyan.bind(ctx);
  ctx.bgWhite = $.bgWhite.bind(ctx);

  return ctx;
}

/**
 * Initialise a single style block.
 *
 * @param {number} open   ANSI code to open the style.
 * @param {number} close  ANSI code to close the style.
 * @returns {function(string=):any}  Callable that either returns a chainable
 *                                   context (when no argument is supplied) or
 *                                   the styled string.
 */
function init(open, close) {
  const blk = {
    open: `\x1B[${open}m`,
    close: `\x1B[${close}m`,
    rgx: new RegExp(`\\x1b\\[${close}m`, "g")
  };

  /**
   * The actual style function.
   *
   * @param {string|undefined} txt  Text to style, or `undefined` to start a chain.
   * @returns {any}                 Either a chainable context or the styled text.
   */
  return function (txt) {
    // When called as a method of a chain (`this` is the context object)
    if (this !== undefined && this.has !== undefined) {
      // Record the style if it hasn't been added yet.
      if (!this.has.includes(open)) {
        this.has.push(open);
        this.keys.push(blk);
      }

      // No argument → return the context for further chaining.
      if (txt === undefined) {
        return this;
      }

      // Apply the accumulated styles.
      return $.enabled ? run(this.keys, String(txt)) : String(txt);
    }

    // Called as a plain function: $.red('text') or $.red()
    if (txt === undefined) {
      // Start a new chain with this single style.
      return chain([open], [blk]);
    }

    // Direct usage without chaining.
    return $.enabled ? run([blk], String(txt)) : String(txt);
  };
}

// Export the colour helper object.
module.exports = $;
